import{describe,it,expect,beforeEach}from"vitest";import fs from"fs";import path from"path";describe("Indian Tribal Culture Explorer",()=>{let t;beforeEach(()=>{t=fs.readFileSync(path.resolve(__dirname,"../../pages-common.js"),"utf-8")}),it("contains valid tribes dataset with required fields",()=>{expect(t).toContain("TRIBES_DATA"),expect(t).toContain("name: 'Gond'"),expect(t).toContain("name: 'Santhal'"),expect(t).toContain("name: 'Naga'"),expect(t).toContain("name: 'Toda'"),expect(t).toContain("name: 'Bhil'"),expect(t).toContain("name: 'Khasi'"),expect(t).toContain("name: 'Warli'"),expect(t).toContain("name: 'Bhutia'")}),it("supports regional categorization across all 6 Indian regions",()=>{expect(t).toContain("key: 'north'"),expect(t).toContain("key: 'northeast'"),expect(t).toContain("key: 'central'"),expect(t).toContain("key: 'east'"),expect(t).toContain("key: 'west'"),expect(t).toContain("key: 'south'")}),it("includes search and state/language filtering logic",()=>{expect(t).toContain("tribes-search-input"),expect(t).toContain("tribes-state-select"),expect(t).toContain("tribes-language-select"),expect(t).toContain("populateDropdowns")})});